package nx.updater;
import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.security.*;import java.security.spec.*;import java.util.*;import java.net.URI;
public final class UpdateManifest {
 public final String version,platform,channel,protocol,mode,fromVersion,notes;public final List<Entry> files=new ArrayList<>();public final Map<String,String> dependencies=new LinkedHashMap<>();public long totalBytes;
 public static final class Entry {public String path,url,sha256,oldSha256,action;public long size;}
 private UpdateManifest(byte[] raw){Map<String,Object> m=Json.object(Json.parse(new String(raw,StandardCharsets.UTF_8)));if(Json.num(m,"schemaVersion")!=1)throw new IllegalArgumentException("Esquema no compatible");version=Json.str(m,"version");new SemVer(version);platform=Json.str(m,"platform");channel=Json.str(m,"channel");protocol=Json.str(m,"protocol");mode=Json.str(m,"mode");if(!mode.equals("FULL")&&!mode.equals("PATCH"))throw new IllegalArgumentException("Modo inválido");fromVersion=(String)m.getOrDefault("fromVersion","");notes=Json.str(m,"notes");
  if(m.containsKey("dependencies"))for(Map.Entry<String,Object> e:Json.object(m.get("dependencies")).entrySet())dependencies.put(e.getKey(),String.valueOf(e.getValue()));
  Set<String> paths=new HashSet<>();for(Object o:Json.array(m.get("files"))){Map<String,Object> f=Json.object(o);Entry e=new Entry();e.path=Json.str(f,"path");safeRelative(e.path);if(!paths.add(e.path.toLowerCase(Locale.ROOT)))throw new IllegalArgumentException("Ruta repetida");e.action=Json.str(f,"action");if(!Arrays.asList("ADD","REPLACE","DELETE").contains(e.action))throw new IllegalArgumentException("Acción inválida");e.oldSha256=(String)f.getOrDefault("oldSha256","");if(!e.action.equals("ADD"))validHash(e.oldSha256);if(!e.action.equals("DELETE")){e.size=Json.num(f,"size");e.sha256=Json.str(f,"sha256");validHash(e.sha256);e.url=Json.str(f,"url");if(e.size<0||e.size>512L*1024*1024)throw new IllegalArgumentException("Tamaño inválido");totalBytes=Math.addExact(totalBytes,e.size);}files.add(e);}if(files.isEmpty()||files.size()>20000||totalBytes>4L*1024*1024*1024)throw new IllegalArgumentException("Paquete fuera de límites");
 }
 public static UpdateManifest verified(byte[] raw,byte[] signature,PublicKey key)throws Exception{if(raw.length>4*1024*1024||signature.length>16384)throw new SecurityException("Manifiesto demasiado grande");if(!(key instanceof java.security.interfaces.RSAPublicKey)||((java.security.interfaces.RSAPublicKey)key).getModulus().bitLength()<2048)throw new SecurityException("Clave RSA mínima2048 bits");Signature s=Signature.getInstance("SHA256withRSA");s.initVerify(key);s.update(raw);if(!s.verify(Base64.getMimeDecoder().decode(signature)))throw new SecurityException("Firma digital no confiable");return new UpdateManifest(raw);}
 public void compatible(String installed,String p,String c,String lan)throws Exception{if(channel.equals("STABLE")&&new SemVer(version).prerelease())throw new SecurityException("Prerelease fuera de STABLE");if(!platform.equals(p))throw new SecurityException("Plataforma diferente");if(!Arrays.asList("DEVELOPMENT","RELEASE CANDIDATE","STABLE").contains(channel)||!channel.equals(c))throw new SecurityException("Canal no instalable");if(new SemVer(version).compareTo(new SemVer(installed))<=0)throw new SecurityException("No es una versión posterior");if(mode.equals("PATCH")&&!fromVersion.equals(installed))throw new SecurityException("Parche para otra versión base");if(!protocol.equals(lan))throw new SecurityException("Requiere migración de protocolo: "+protocol);for(String dep:dependencies.keySet())if(!dep.equals("javaMajor"))throw new SecurityException("Dependencia no reconocida: "+dep);if(dependencies.containsKey("javaMajor")){String j=System.getProperty("java.specification.version");int v=Integer.parseInt(j.startsWith("1.")?j.substring(2):j);if(v<Integer.parseInt(dependencies.get("javaMajor")))throw new SecurityException("Java más reciente requerido");}}
 public static PublicKey publicKey(Path p)throws Exception{String s=new String(Files.readAllBytes(p),StandardCharsets.US_ASCII).replace("-----BEGIN PUBLIC KEY-----","").replace("-----END PUBLIC KEY-----","").replaceAll("\\s","");return KeyFactory.getInstance("RSA").generatePublic(new X509EncodedKeySpec(Base64.getDecoder().decode(s)));}
 static void validHash(String s){if(s==null||!s.matches("[a-f0-9]{64}"))throw new IllegalArgumentException("SHA256 inválido");}
 public static void safeRelative(String p){if(p==null||p.length()>220||p.contains("\\")||p.contains(":")||p.startsWith("/")||p.contains("//")||p.indexOf(34)>=0||p.matches(".*[<>|?*].*")||p.chars().anyMatch(c->c<32))throw new SecurityException("Ruta insegura");for(String part:p.split("/",-1)){if(part.isEmpty()||part.equals(".")||part.equals("..")||part.endsWith(".")||part.endsWith(" ")||part.matches("(?i)(con|prn|aux|nul|com[0-9]|lpt[0-9])(\\..*)?"))throw new SecurityException("Ruta insegura");}if(!(p.startsWith("res/")||p.startsWith("lib/")||p.startsWith("runtime/")||p.startsWith("src/")||p.startsWith("cooked/")||p.startsWith("presentation/")||p.startsWith("cb4/")||p.matches("[A-Za-z0-9_-]+\\.xex")||p.matches("[A-Za-z0-9_-]+\\.jar")&&!p.equals("nx-updater.jar")||p.equals("version.properties")))throw new SecurityException("Datos del usuario o actualizador protegidos: "+p);}
 public static Path target(Path root,String p)throws Exception{safeRelative(p);Path r=root.toAbsolutePath().normalize();if(Files.isSymbolicLink(r))throw new SecurityException("Raíz simbólica");Path t=r.resolve(p).normalize();if(!t.startsWith(r))throw new SecurityException("Ruta exterior");for(Path x=t;x!=null&&x.startsWith(r);x=x.getParent())if(Files.isSymbolicLink(x))throw new SecurityException("Enlace simbólico en instalación");return t;}
}
